contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(address acct) public payable {
        require(acct != address(0), "zero address");
        require(acct != address(this), "use a fresh address");
        require(acct != address(c), "not c");

        uint256 beforeAcct = c.balances(acct); if (__ESBMC_reverted()) return;
        uint256 beforeContract = address(c).balance;

        c.withdraw(); if (__ESBMC_reverted()) return;

        uint256 afterAcct = c.balances(acct); if (__ESBMC_reverted()) return;
        uint256 afterContract = address(c).balance;

        assert(afterAcct == beforeAcct && afterContract == beforeContract);
    }

    receive() external payable {}
}

