pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {keepMyEther} from "../src/keepMyEther.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    keepMyEther c;

    function setUp() public {
        c = new keepMyEther();
    }

    function _run(address acct) internal {
        vm.assume(acct != address(0));
        vm.assume(acct != address(this));
        vm.assume(acct != address(c));
        uint256 beforeAcct;
        try c.balances(acct) returns (uint256 __r) { beforeAcct = __r; } catch { return; }
        uint256 beforeContract = address(c).balance;
        try c.withdraw() {} catch { return; }
        uint256 afterAcct;
        try c.balances(acct) returns (uint256 __r) { afterAcct = __r; } catch { return; }
        uint256 afterContract = address(c).balance;
        assertTrue(afterAcct == beforeAcct && afterContract == beforeContract);
    }

    function testFuzz_run(address acct) public {
